'use strict';
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const journalTitle='北欧追光手记 | Nordic Journal 2026';
const journalDescription='挪威与冰岛的秋冬旅行，记录极光、鲸群、峡湾与冰川。';
const smallPhoto=k=>PHOTO_VARIANTS[pImage(k)]?.small||pImage(k);
const photoAttributes=src=>{const v=PHOTO_VARIANTS[src];return v?`srcset="${v.small} ${v.smallWidth}w, ${src} ${v.width}w" sizes="(max-width:760px) calc(100vw - 40px), 860px"`:'';};
const springs=new WeakMap();
function moveSlider(el){const buttons=[...el.querySelectorAll(':scope > button')];if(!buttons.length)return;let slider=el.querySelector(':scope > .segment-slider');if(!slider){slider=document.createElement('span');slider.className='segment-slider';slider.setAttribute('aria-hidden','true');el.prepend(slider);}const selected=buttons.find(b=>b.getAttribute('aria-pressed')==='true'||b.classList.contains('active'))||buttons[0];let s=springs.get(el);const target=selected.offsetLeft;slider.style.width=selected.offsetWidth+'px';if(!s){s={x:target,v:0,target,frame:0};springs.set(el,s);slider.style.transform=`translateX(${target}px)`;}s.target=target;if(reduced()){cancelAnimationFrame(s.frame);s.frame=0;s.x=target;s.v=0;slider.style.transform=`translateX(${target}px)`;return;}if(s.frame)return;let last=performance.now();function step(t){const dt=Math.min((t-last)/1000,.15);last=t;const alpha=22,omega=Math.sqrt(166),delta=s.x-s.target,co=Math.cos(omega*dt),si=Math.sin(omega*dt),decay=Math.exp(-alpha*dt),carry=(s.v+alpha*delta)/omega;s.x=s.target+decay*(delta*co+carry*si);s.v=decay*((-alpha*delta+omega*carry)*co+(-alpha*carry-omega*delta)*si);slider.style.transform=`translateX(${s.x}px)`;if(Math.abs(s.target-s.x)<.1&&Math.abs(s.v)<.15){s.x=s.target;slider.style.transform=`translateX(${s.x}px)`;s.frame=0;}else s.frame=requestAnimationFrame(step);}s.frame=requestAnimationFrame(step);}
function setupSegments(){document.querySelectorAll('.choice,.transport-grid,.segments,.bottom-nav').forEach(el=>{el.classList.add('shared-segments');moveSlider(el);});}
async function copyLink(url,label='链接'){try{if(navigator.clipboard&&isSecureContext){await navigator.clipboard.writeText(url);toast(label+'已复制');return;}}catch{}const ta=document.createElement('textarea');ta.value=url;ta.style.cssText='position:fixed;top:0;left:0;width:1px;height:1px;opacity:.01';document.body.append(ta);ta.focus();ta.select();let ok=false;try{ok=document.execCommand('copy');}catch{}ta.remove();if(ok)toast(label+'已复制');else openDrawer('复制'+label,`<p>长按下方内容复制</p><input class="share-url" readonly value="${esc(url)}" aria-label="${esc(label)}">`);}
async function shareJournal(){const url=location.href;if(/MicroMessenger/i.test(navigator.userAgent)){openDrawer('分享路书',`<p class="detail-desc">点击微信右上角「…」，选择「发送给朋友」或「分享到朋友圈」。</p><p>可复制当前页面链接，保留已选日期。微信卡片展示由微信决定。</p><button class="primary-link" data-copy-link>复制当前链接</button>`);return;}if(navigator.share){try{await navigator.share({title:journalTitle,text:journalDescription,url});return;}catch(e){if(e.name==='AbortError')return;}}await copyLink(url);}
const viewer=document.createElement('div');viewer.className='photo-viewer';viewer.hidden=true;viewer.setAttribute('role','dialog');viewer.setAttribute('aria-modal','true');viewer.setAttribute('aria-label','风景照片查看器');viewer.innerHTML='<div class="photo-toolbar"><span id="photoCounter"></span><button data-photo-close aria-label="关闭照片">关闭 ×</button></div><div class="photo-stage"><img alt="" draggable="false"></div><div class="photo-bottom"><button data-photo-prev aria-label="上一张照片">←</button><div><p id="photoCaption"></p><small>左右滑动切换 · 双击或双指缩放</small></div><button data-photo-next aria-label="下一张照片">→</button></div>';document.body.append(viewer);
let galleryToken=0;let gallery=[],photoIndex=0,photoFocus=null,originRect=null,oldOverflow='',zoom=1;const photo=viewer.querySelector('img'),stage=viewer.querySelector('.photo-stage');
function photoAnimate(from,to){if(reduced())return;photo.getAnimations().forEach(a=>a.cancel());return photo.animate([{transform:from},{transform:to}],{duration:230,easing:'cubic-bezier(.2,0,0,1)'});}
function showPhoto(index,opening=false){const token=++galleryToken;photo.getAnimations().forEach(a=>a.cancel());pointers.clear();photoIndex=(index+gallery.length)%gallery.length;const key=gallery[photoIndex];photo.src=pImage(key);photo.alt=DATA.places[key]?.name||CREDITS[key]?.title||'沿途风景';zoom=1;photo.style.transform='';stage.scrollTo(0,0);$('#photoCounter').textContent=`${photoIndex+1} / ${gallery.length}`;$('#photoCaption').textContent=photo.alt;photo.onload=()=>{if(token!==galleryToken||viewer.hidden)return;if(opening&&originRect){const r=photo.getBoundingClientRect();photoAnimate(`translate(${originRect.x+originRect.width/2-r.x-r.width/2}px,${originRect.y+originRect.height/2-r.y-r.height/2}px) scale(${originRect.width/r.width},${originRect.height/r.height})`,'none');}else photoAnimate('translateX(12px)','none');};}
function openPhoto(key,source){galleryToken++;photoFocus=document.activeElement;gallery=[...new Set([key,...[...document.querySelectorAll('[data-photo]')].map(x=>x.dataset.photo)])].filter(k=>pImage(k));originRect=source?.getBoundingClientRect();oldOverflow=document.body.style.overflow;viewer.hidden=false;document.body.style.overflow='hidden';for(const id of ['mainShell','bottomNav','topbar'])$('#'+id).inert=true;if($('#overlay').classList.contains('open'))$('#overlay').inert=true;showPhoto(0,true);viewer.querySelector('[data-photo-close]').focus({preventScroll:true});}
function closePhoto(){const token=++galleryToken;pointers.clear();const finish=()=>{if(token!==galleryToken)return;viewer.hidden=true;document.body.style.overflow=oldOverflow;const drawerOpen=$('#overlay').classList.contains('open');for(const id of ['mainShell','bottomNav','topbar'])$('#'+id).inert=drawerOpen;$('#overlay').inert=!drawerOpen;photoFocus?.focus({preventScroll:true});};if(reduced()||!photoFocus?.isConnected){finish();return;}const r=photo.getBoundingClientRect(),target=photoFocus.querySelector('img')?.getBoundingClientRect();if(target&&gallery[photoIndex]===photoFocus.dataset.photo){const a=photoAnimate('none',`translate(${target.x+target.width/2-r.x-r.width/2}px,${target.y+target.height/2-r.y-r.height/2}px) scale(${target.width/r.width},${target.height/r.height})`);a?.finished.then(finish,finish);}else finish();}
const pointers=new Map();let startX=0,pinchDistance=0,pinchZoom=1,swipeAllowed=true;
stage.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===1){startX=e.clientX;swipeAllowed=zoom===1;}if(pointers.size===2){swipeAllowed=false;const [a,b]=[...pointers.values()];pinchDistance=Math.hypot(a[0]-b[0],a[1]-b[1]);pinchZoom=zoom;}});
stage.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2){const [a,b]=[...pointers.values()];zoom=Math.max(1,Math.min(3,pinchZoom*Math.hypot(a[0]-b[0],a[1]-b[1])/pinchDistance));photo.style.transform=`scale(${zoom})`;}});
stage.addEventListener('pointerup',e=>{if(pointers.size===1&&swipeAllowed&&Math.abs(e.clientX-startX)>55)showPhoto(photoIndex+(e.clientX<startX?1:-1));pointers.delete(e.pointerId);});
stage.addEventListener('pointercancel',e=>pointers.delete(e.pointerId));
stage.addEventListener('dblclick',()=>{zoom=zoom===1?2:1;photo.style.transform=`scale(${zoom})`;});
document.addEventListener('keydown',e=>{if(viewer.hidden)return;if(['Escape','Tab','ArrowRight','ArrowLeft'].includes(e.key))e.stopImmediatePropagation();if(e.key==='Escape'){e.preventDefault();closePhoto();}if(e.key==='ArrowRight')showPhoto(photoIndex+1);if(e.key==='ArrowLeft')showPhoto(photoIndex-1);if(e.key==='Tab'){const buttons=[...viewer.querySelectorAll('button')],first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}},true);
